-- 500 author-written fictional training cases per game: 12 original + 488 contextual variations.
-- The additional scenarios comprise 294 serious and 194 light cases, yielding a 300:200 bank.
-- 25 teacher-directed all-audience cases are excluded from automatic single-recipient dispatch.
create or replace function private.seed_event_bank_extended(p_game uuid)
returns integer language plpgsql security definer set search_path=public,private,pg_temp as $$
declare base_added integer; expanded integer;
begin
 base_added:=private.seed_event_bank(p_game);
 with seeds(kind,seq,title,situation,category,roles) as (
 values
 ('serious',1,'Аварийное жильё','Экспертиза обнаружила трещины в доме, где живут 120 семей. Переселение обойдётся дорого, а ближайшее общежитие рассчитано только на половину жильцов.','Муниципальное управление',ARRAY['муницип','депутат','министр']::text[]),
('serious',2,'Водозабор на реке','Уровень реки упал и действующий водозабор обеспечивает поселение лишь на две трети прежнего объёма. Соседний район предлагает совместный проект.','Экология',ARRAY['министр','муницип','правительств']::text[]),
('serious',3,'Отопительный сезон','В котельной изношен основной насос, а до заморозков осталось две недели. Ремонт и резервная техника финансируются из одной статьи.','Жилищно-коммунальное хозяйство',ARRAY['муницип','министр','правительств']::text[]),
('serious',4,'Поликлиника без терапевтов','Трое врачей одновременно уволились из районной больницы. Жители требуют сохранить очные приёмы, а регион готов поддержать мобильную бригаду.','Здравоохранение',ARRAY['министр','депутат','правительств']::text[]),
('serious',5,'Подвоз школьников','Автобус для детей из пяти деревень вышел из строя. Уроки продолжаются, но резервный маршрут добавляет к дороге почти час.','Образование',ARRAY['министр','муницип','депутат']::text[]),
('serious',6,'Лесной пожар у посёлка','Сильный ветер разносит дым от лесного пожара в сторону жилых кварталов. Пожарные просят технику и раннее решение об эвакуации.','Безопасность',ARRAY['министр','глава города','администрац']::text[]),
('serious',7,'Паводок и дамба','После затяжных дождей возникла угроза подтопления посёлка. Временная дамба защитит часть домов, но изменит сток воды к соседнему району.','Безопасность',ARRAY['муницип','министр','правительств']::text[]),
('serious',8,'Контракт на переработку отходов','Муниципалитет выбирает подрядчика для переработки отходов. Более дешёвое предложение требует новой перегрузочной станции возле жилых домов.','Экология',ARRAY['муницип','депутат','министр']::text[]),
('serious',9,'Интернет для отдалённых сёл','Сельские школы жалуются на нестабильный доступ в сеть. Оператор просит софинансирование инфраструктуры, которую частично смогут использовать жители.','Цифровая инфраструктура',ARRAY['министр','депутат','правительств']::text[]),
('serious',10,'Доступность городской администрации','Общественная проверка выявила, что входы в три учреждения недоступны для маломобильных граждан. Проект переоборудования конкурирует с ремонтом крыш.','Социальная политика',ARRAY['муницип','депутат','министр']::text[]),
('serious',11,'Закрытие градообразующего предприятия','Крупный работодатель объявил о сокращении сотен рабочих мест. Региональная служба занятости предлагает переобучение, но программу ещё не финансировали.','Экономика',ARRAY['министр','правительств','депутат']::text[]),
('serious',12,'Оплата труда педагогов','Учителя небольших школ просят компенсации за работу в труднодоступных территориях. Финансирование придётся согласовать между муниципалитетом и регионом.','Образование',ARRAY['министр','депутат','правительств']::text[]),
('serious',13,'Содержание районных дорог','После зимы обследование показало серьёзные повреждения дороги к больнице. Дорожный фонд позволяет провести только часть необходимых работ.','Муниципальное управление',ARRAY['муницип','депутат','правительств']::text[]),
('serious',14,'Утечка на промышленной площадке','На складе химических реагентов произошла утечка; предприятие заявляет, что выброс локализован. Жители требуют независимых замеров и открытой информации.','Безопасность',ARRAY['министр','муницип','правительств']::text[]),
('serious',15,'Дефицит бюджета','Новый макропрогноз уменьшил ожидаемые доходы республики. Финансирование социальной программы, транспорта и резервного фонда необходимо пересмотреть.','Экономика',ARRAY['правительств','министр','депутат']::text[]),
('serious',16,'Конфликт интересов в закупке','Журналисты обнаружили родственную связь между членом комиссии и руководителем фирмы, выигравшей конкурс. Законность процедуры требует проверки.','Государственное управление',ARRAY['депутат','муницип','министр']::text[]),
('serious',17,'Недостоверные сведения о ремонте','В городском сообществе распространилось сообщение, будто школа уже закрыта из-за аварийности. Администрация располагает противоречивыми актами обследования.','Образование',ARRAY['министр','муницип','депутат']::text[]),
('serious',18,'Транспортный тариф','Перевозчик заявляет об убытках и требует повысить стоимость проезда. Совет депутатов обсуждает компенсации льготникам и качество маршрутов.','Муниципальное управление',ARRAY['депутат','муницип','правительств']::text[]),
('serious',19,'Сеть библиотек','Два библиотечных филиала нуждаются в капитальном ремонте. Объединение учреждений снизит расходы, но увеличит расстояние для пожилых читателей.','Культура и протокол',ARRAY['муницип','депутат','министр']::text[]),
('serious',20,'Бюджетные слушания','На слушания по бюджету поступили десятки предложений; часть противоречит уже подписанным обязательствам. Нужно предложить процедуру приоритизации.','Государственное управление',ARRAY['депутат','правительств','муницип']::text[]),
('serious',21,'Перебои с лекарствами','Пациенты сообщают о нехватке препаратов в районных больницах. Поставщик связывает ситуацию с транспортом, а врачи предлагают межрайонное перераспределение.','Здравоохранение',ARRAY['министр','правительств','депутат']::text[]),
('serious',22,'Школьное питание','Родители зафиксировали ухудшение качества питания. Подрядчик предлагает изменить меню, но необходимо проверить безопасность и соблюдение контракта.','Образование',ARRAY['министр','муницип','депутат']::text[]),
('serious',23,'Молодёжная миграция','Из небольшого города уезжают выпускники. Работодатели предлагают стипендии за обязательство вернуться, студенты просят более гибкие условия.','Социальная политика',ARRAY['депутат','министр','правительств']::text[]),
('serious',24,'Контроль гидротехнических сооружений','Плановая инспекция обнаружила дефекты на защитном шлюзе. Частичный ремонт возможен сейчас, полная реконструкция требует регионального соглашения.','Безопасность',ARRAY['министр','муницип','правительств']::text[]),
('serious',25,'Подарок чиновнику','После заключения контракта руководитель учреждения получил дорогой подарок от подрядчика. Необходимо проверить возможный конфликт интересов и процедуру декларирования.','Государственное управление',ARRAY['министр','депутат','муницип']::text[]),
('serious',26,'Межбюджетные трансферты','Два района оспаривают методику распределения региональных субсидий. Один нуждается в ремонте дорог, другой — в экстренной модернизации водоснабжения.','Экономика',ARRAY['депутат','правительств','министр']::text[]),
('serious',27,'Качество городского воздуха','Мобильная лаборатория зарегистрировала превышение установленных в учебной модели порогов загрязнения. Предприятия просят перепроверить методику измерений.','Экология',ARRAY['министр','муницип','правительств']::text[]),
('serious',28,'Резервная связь на случай ЧС','В горном районе во время метели одновременно отказали две линии связи. Требуется определить ответственных за резервный канал и информационную координацию.','Безопасность',ARRAY['министр','муницип','правительств']::text[]),
('serious',29,'Сельская амбулатория','Малочисленный посёлок рискует потерять амбулаторию из-за дорогого содержания. Жители предлагают совместить выездные приёмы с дистанционными консультациями.','Здравоохранение',ARRAY['министр','депутат','правительств']::text[]),
('serious',30,'Ремонт общежития','Студенты сообщили о проблемах с электропроводкой в общежитии. Руководство предлагает частично закрыть этажи на время ремонта, но переселять учащихся некуда.','Образование',ARRAY['министр','депутат','муницип']::text[]),
('light',1,'Опечатка на городской вывеске','На новом указателе перепутали две буквы в названии улицы. Фотография стала популярной, а подрядчик обещает исправить ошибку только через месяц.','Муниципальное управление',ARRAY[]::text[]),
('light',2,'Кот на заседании','Во время торжественного заседания в зал зашёл кот и занял кресло председателя. В сети требуют сделать его почётным талисманом.','Культура и протокол',ARRAY[]::text[]),
('light',3,'Непослушная лента','На открытии парка церемониальная лента оказалась слишком прочной для ножниц. Запись неудачной попытки разошлась по городским сообществам.','Культура и протокол',ARRAY[]::text[]),
('light',4,'Пропал звук микрофона','За минуту до публичной дискуссии отказали микрофоны. Спикеры уже на сцене, а зрители требуют начать вовремя.','Государственное управление',ARRAY[]::text[]),
('light',5,'Конкурс городского талисмана','Жители выбирают талисман юбилейного фестиваля. В финал одновременно вышли серьёзный архитектурный символ и смешной рисунок местного гуся.','Культура и протокол',ARRAY[]::text[]),
('light',6,'Кофе в приёмной','Чиновники шутят, что из-за неисправной кофемашины рабочие встречи стали короче и продуктивнее. Пресс-служба получила запрос на комментарий.','Государственное управление',ARRAY[]::text[]),
('light',7,'Голуби и памятник','В социальных сетях жители спорят, нужно ли защищать новый памятник от голубей или сделать птиц частью необычной фотозоны.','Культура и протокол',ARRAY[]::text[]),
('light',8,'Музыкальный день района','Организаторы фестиваля предложили чиновникам спеть вместе с молодёжными коллективами. Одни считают участие важным, другие опасаются формальности.','Культура и протокол',ARRAY[]::text[]),
('light',9,'Фонтан сюрпризов','Городской фонтан неожиданно начал работать под утро вместо заявленного времени. Молодёжь сняла забавное видео и предлагает новый график.','Муниципальное управление',ARRAY[]::text[]),
('light',10,'Очередь на фестивале','На городской фестиваль пришло больше гостей, чем ожидалось. Организаторы могут изменить маршрут очереди или открыть дополнительную площадку.','Культура и протокол',ARRAY[]::text[]),
('light',11,'Название нового мостика','Горожане предложили назвать пешеходный мостик в честь местной легенды о потерянном зонте. Архитекторы сомневаются в уместности.','Муниципальное управление',ARRAY[]::text[]),
('light',12,'Соревнование школьных огородов','Пять школ устроили конкурс общественных огородов. Победители просят у муниципалитета место для совместной теплицы.','Образование',ARRAY[]::text[]),
('light',13,'Ошибка в городском календаре','Афиша Дня города содержит неверную дату одного из концертов. Организаторы уже распространили несколько тысяч экземпляров.','Культура и протокол',ARRAY[]::text[]),
('light',14,'Необычная скульптура','Художник предложил установить у набережной огромную разноцветную скамейку. Проект получил множество мемов и почти равное число сторонников и противников.','Культура и протокол',ARRAY[]::text[]),
('light',15,'Перевёрнутый флажок','На городском празднике декоративный флажок повесили вверх ногами. Очевидцы обсуждают, был ли это художественный замысел.','Культура и протокол',ARRAY[]::text[]),
('light',16,'Прогноз погоды от мэра','Перед открытым праздником мэр пошутил, что подписал распоряжение о солнечной погоде. Через пять минут начался ливень.','Муниципальное управление',ARRAY[]::text[]),
('light',17,'Фестиваль огромных тыкв','Местные фермеры предлагают фестиваль гигантских тыкв. Торговые места и уборка после праздника ещё не согласованы.','Культура и протокол',ARRAY[]::text[]),
('light',18,'Арт-объект из вторсырья','Школьники создали яркую скульптуру из переработанного пластика. Горожане предлагают разместить её в центре площади.','Экология',ARRAY[]::text[]),
('light',19,'Уличный обмен книгами','Жители организовали неформальный книжный обмен в старой телефонной будке. Библиотека хочет поддержать акцию, но у неё нет ответственного.','Культура и протокол',ARRAY[]::text[]),
('light',20,'Марафон против бумажной волокиты','Молодёжный совет предлагает соревноваться в сокращении числа бумажных форм. Больше всего предложений касается внутренних справок и дублирующих подписей.','Государственное управление',ARRAY[]::text[])
 ),
 twists(kind,seq,label,detail) as (
 values
 ('serious',1,'Сокращение сметы','Неожиданно региональная смета уменьшилась на 18%. Сформулируйте, какую часть проекта оставить и как публично объяснить приоритеты.'),
('serious',2,'Общественное возражение','Жители собрали инициативную группу и требуют альтернативного решения. Определите, кто и в каком формате проведёт консультации.'),
('serious',3,'Противоречивая экспертиза','Два эксперта пришли к разным выводам. Опишите, какое дополнительное исследование необходимо и можно ли действовать до него.'),
('serious',4,'Спор о полномочиях','Муниципальный и региональный органы утверждают, что вопрос относится к полномочиям друг друга. Укажите способ согласования компетенций.'),
('serious',5,'Короткий срок','До обязательного контрольного срока осталось пять рабочих дней. Выберите временные меры, ответственных и порядок отчётности.'),
('serious',6,'Удалённая территория','Один из наиболее пострадавших населённых пунктов находится далеко от транспортного узла. Учтите проблему доступа к услугам.'),
('serious',7,'Правовые возражения','Юридическая служба обнаружила риск обжалования первоначального плана. Решите, какие документы необходимо изменить до реализации.'),
('serious',8,'Альтернативный подрядчик','Появился новый поставщик с другим графиком и стоимостью. Предложите критерии сравнения без фаворитизма.'),
('serious',9,'Информационная утечка','В сеть попал неполный черновик решения, вызвавший тревогу. Подготовьте проверяемое публичное разъяснение без сокрытия проблем.'),
('serious',10,'Несогласные специалисты','Профильные специалисты не смогли согласовать один вариант. Определите процедуру принятия решения и документирования разногласий.'),
('light',1,'Вирусное видео','Видео с ситуацией набрало популярность среди жителей. Подготовьте доброжелательный и содержательный ответ администрации.'),
('light',2,'Нулевой дополнительный бюджет','Казначейство не одобрило дополнительные расходы на эту ситуацию. Предложите инициативу, не требующую новых бюджетных средств.'),
('light',3,'Студенческие волонтёры','Студенты готовы помочь, но требуют понятного расписания и ответственного куратора. Решите, стоит ли их привлекать.'),
('light',4,'Петиция жителей','Появилась петиция с предложением превратить ситуацию в ежегодную городскую традицию. Нужен прозрачный способ проверки спроса.'),
('light',5,'Шутка блогера','Популярный местный блогер преувеличил проблему и просит комментарий. Опишите, как корректно реагировать без конфликта.'),
('light',6,'Прямой эфир','Ситуация попала в прямой эфир городского праздника. Решите, кто выступит от учреждения и как ответит на вопросы публики.'),
('light',7,'Межрайонное соревнование','Соседний район предлагает устроить дружеское соревнование. Оцените необходимые ресурсы и критерии победы.'),
('light',8,'Сбой из-за погоды','Сильный ветер внезапно изменил планы организаторов. Предложите безопасный и доступный резервный сценарий.'),
('light',9,'Ошибочная фотография','Оказалось, что фотография события относится к другому году. Предложите порядок проверки и обновления публичной информации.'),
('light',10,'Открытое голосование','Организаторы хотят вынести два варианта решения на публичный опрос. Сформулируйте нейтральные варианты ответа и способ учёта мнений.')
 ),
 expanded_cases as (
 select s.*,t.seq twist_no,t.label twist_label,t.detail twist_detail,
 row_number() over(order by s.kind desc,s.seq,t.seq) as ordinal
 from seeds s join twists t on t.kind=s.kind
 where s.seq<case when s.kind='serious' then 30 else 20 end or t.seq<=4
 )
 insert into public.event_cases(game_id,case_key,title,situation,category,seriousness,audience,allowed_roles,verified,status,source_note)
 select p_game,'bank-expanded-'||e.kind||'-'||lpad(e.seq::text,2,'0')||'-'||lpad(e.twist_no::text,2,'0'),
 e.title||': '||e.twist_label,
 e.situation||E'\\n\\n'||e.twist_detail||' Обоснуйте своё решение с учётом интересов участников, бюджета, полномочий и ожидаемых последствий.',
 e.category,e.kind,
 case when e.kind='serious' and e.seq<=2 or (e.kind='serious' and e.seq=3 and e.twist_no<=5)
 then 'all' else 'single' end,
 e.roles,false,'ready','Авторский вымышленный учебный сценарий GOS//SIMS, не описание реальных событий.'
 from expanded_cases e
 where not exists (
   select 1 from public.event_cases c where c.game_id=p_game
     and c.case_key='bank-expanded-'||e.kind||'-'||lpad(e.seq::text,2,'0')||'-'||lpad(e.twist_no::text,2,'0')
 );
 get diagnostics expanded=row_count;
 return base_added+expanded;
end;
$$;
revoke all on function private.seed_event_bank_extended(uuid) from public,anon,authenticated;
create or replace function public.seed_game_event_bank(p_game_id uuid)
returns integer language plpgsql security definer set search_path=public,private,pg_temp as $$
begin
 if not private.is_game_teacher(p_game_id) then raise exception 'Teacher access required';end if;
 return private.seed_event_bank_extended(p_game_id);
end;
$$;
revoke all on function public.seed_game_event_bank(uuid) from public,anon;
grant execute on function public.seed_game_event_bank(uuid) to authenticated;

create or replace function public.configure_game_event_autopilot(
 p_game_id uuid,p_enabled boolean,p_interval_hours integer,p_activity_weight numeric,
 p_max_daily integer,p_trust_per_20 numeric,p_backlog_penalty numeric)
returns void language plpgsql security definer set search_path=public,private,pg_temp as $$
begin
 if not private.is_game_teacher(p_game_id) then raise exception 'Teacher access required';end if;
 if p_interval_hours not between 4 and 72 or p_activity_weight not between 0 and 2
    or p_max_daily not between 1 and 3 or p_trust_per_20 not between 0 and 4
    or p_backlog_penalty not between 0 and 2 then raise exception 'Invalid event settings';end if;
 perform private.seed_event_bank_extended(p_game_id);
 insert into public.event_auto_settings(game_id,enabled,interval_hours,activity_weight,max_daily,trust_per_20,backlog_penalty)
 values(p_game_id,p_enabled,p_interval_hours,p_activity_weight,p_max_daily,p_trust_per_20,p_backlog_penalty)
 on conflict(game_id) do update set enabled=excluded.enabled,interval_hours=excluded.interval_hours,
 activity_weight=excluded.activity_weight,max_daily=excluded.max_daily,trust_per_20=excluded.trust_per_20,
 backlog_penalty=excluded.backlog_penalty,updated_at=now();
end;
$$;
revoke all on function public.configure_game_event_autopilot(uuid,boolean,integer,numeric,integer,numeric,numeric) from public,anon;
grant execute on function public.configure_game_event_autopilot(uuid,boolean,integer,numeric,integer,numeric,numeric) to authenticated;

-- Public records use "bank" prefixes. No actual historical claim is made by the fictional stories.
select private.seed_event_bank_extended(id) from public.games;
